1	use std::num::IntErrorKind;
2	
3	use ecow::{EcoString, EcoVec, eco_format, eco_vec};
4	use typst_utils::default_math_class;
5	use unicode_ident::{is_xid_continue, is_xid_start};
6	use unicode_math_class::MathClass;
7	use unicode_script::{Script, UnicodeScript};
8	use unicode_segmentation::UnicodeSegmentation;
9	use unscanny::Scanner;
