11	use crate::ast::NonDecimalBase;
12	use crate::{SyntaxKind, SyntaxMode, SyntaxNode};
13	
14	/// An iterator over a source code string which returns tokens.
15	#[derive(Clone)]
16	pub(super) struct Lexer<'s> {
17	    /// The scanner: contains the underlying string and location as a "cursor".
18	    s: Scanner<'s>,
19	    /// The mode the lexer is in. This determines which kinds of tokens it
20	    /// produces.
21	    mode: SyntaxMode,
22	    /// An error plus hints for the current token being produced. This is always
23	    /// `None` between calls to [`Lexer::next`].
24	    error: Option<(EcoString, EcoVec<EcoString>)>,
25	}
26	
27	impl<'s> Lexer<'s> {
28	    /// Create a new lexer with the given mode.
29	    pub fn new(text: &'s str, mode: SyntaxMode) -> Self {
30	        Self { s: Scanner::new(text), mode, error: None }
31	    }
32	
33	    /// Get the current lexing mode.
34	    pub fn mode(&self) -> SyntaxMode {
35	        self.mode
36	    }
37	
38	    /// Change the lexing mode.
39	    pub fn set_mode(&mut self, mode: SyntaxMode) {
40	        self.mode = mode;
41	    }
42	
43	    /// The index in the string at which the last token ends and next token
44	    /// will start.
45	    pub fn cursor(&self) -> usize {
46	        self.s.cursor()
47	    }
48	
49	    /// Jump to the given index in the string.
50	    pub fn jump(&mut self, index: usize) {
51	        self.s.jump(index);
52	    }
53	
54	    /// The number of characters until the most recent newline from an index.
55	    pub fn column(&self, index: usize) -> usize {
56	        let mut s = self.s; // Make a new temporary scanner (cheap).
57	        s.jump(index);
58	        s.before().chars().rev().take_while(|&c| !is_newline(c)).count()
59	    }
60	}
61	
62	impl Lexer<'_> {
63	    /// Construct a full-positioned syntax error.
64	    fn error(&mut self, message: impl Into<EcoString>) -> SyntaxKind {
65	        debug_assert!(self.error.is_none());
66	        self.error = Some((message.into(), eco_vec![]));
67	        SyntaxKind::Error
68	    }
69	
70	    /// If the current node is an error, adds a hint.
71	    fn hint(&mut self, message: impl Into<EcoString>) {
72	        if let Some((_message, hints)) = &mut self.error {
73	            hints.push(message.into());
74	        }
75	    }
76	}
77	
78	/// Shared methods with all [`SyntaxMode`].
79	impl Lexer<'_> {
80	    /// Return the next token in our text. Returns both the [`SyntaxNode`]
81	    /// and the raw [`SyntaxKind`] to make it more ergonomic to check the kind
82	    pub fn next(&mut self) -> (SyntaxKind, SyntaxNode) {
83	        debug_assert!(self.error.is_none());
84	        let start = self.s.cursor();
85	
86	        let kind = match self.s.eat() {
87	            Some(c) if is_space(c, self.mode) => self.whitespace(start, c),
88	            Some('#') if start == 0 && self.s.eat_if('!') => self.shebang(),
89	            Some('/') if self.s.eat_if('/') => self.line_comment(),
90	            Some('/') if self.s.eat_if('*') => self.block_comment(),
91	            Some('*') if self.s.eat_if('/') => {
92	                let error = self.error("unexpected end of block comment");
93	                self.hint(
94	                    "consider escaping the `*` with a backslash or \
95	                     opening the block comment with `/*`",
96	                );
97	                error
98	            }
99	            Some('`') if self.mode != SyntaxMode::Math => return self.raw(),
100	            Some(c) => match self.mode {
101	                SyntaxMode::Markup => self.markup(start, c),
102	                SyntaxMode::Math => match self.math(start, c) {
103	                    (kind, None) => kind,
104	                    (kind, Some(node)) => return (kind, node),
105	                },
106	                SyntaxMode::Code => self.code(start, c),
107	            },
108	
109	            None => SyntaxKind::End,
110	        };
111	
112	        let text = self.s.from(start);
113	        let node = match self.error.take() {
114	            Some((message, hints)) => SyntaxNode::error(message, text).with_hints(hints),
115	            None => SyntaxNode::leaf(kind, text),
116	        };
117	        (kind, node)
118	    }
119	
120	    /// Eat whitespace characters greedily.
121	    fn whitespace(&mut self, start: usize, c: char) -> SyntaxKind {
122	        let more = self.s.eat_while(|c| is_space(c, self.mode));
123	        let newlines = match c {
124	            // Optimize eating a single space.
125	            ' ' if more.is_empty() => 0,
126	            _ => count_newlines(self.s.from(start)),
127	        };
128	
129	        if self.mode == SyntaxMode::Markup && newlines >= 2 {
130	            SyntaxKind::Parbreak
131	        } else if newlines > 0 {
132	            SyntaxKind::SpaceWithNewline
133	        } else {
134	            SyntaxKind::SpaceNoNewline
135	        }
136	    }
137	
138	    fn shebang(&mut self) -> SyntaxKind {
139	        self.s.eat_until(is_newline);
140	        SyntaxKind::Shebang
141	    }
142	
143	    fn line_comment(&mut self) -> SyntaxKind {
144	        self.s.eat_until(is_newline);
145	        SyntaxKind::LineComment
146	    }
147	
148	    fn block_comment(&mut self) -> SyntaxKind {
149	        let mut state = '_';
150	        let mut depth = 1;
151	
152	        // Find the first `*/` that does not correspond to a nested `/*`.
153	        while let Some(c) = self.s.eat() {
154	            state = match (state, c) {
155	                ('*', '/') => {
156	                    depth -= 1;
157	                    if depth == 0 {
158	                        break;
159	                    }
160	                    '_'
161	                }
162	                ('/', '*') => {
163	                    depth += 1;
164	                    '_'
165	                }
166	                _ => c,
167	            }
168	        }
169	
170	        SyntaxKind::BlockComment
171	    }
172	}
173	
174	/// Raw.
175	impl Lexer<'_> {
176	    /// We parse entire raw segments in the lexer as a convenience to avoid
177	    /// going to and from the parser for each raw section.
178	    fn raw(&mut self) -> (SyntaxKind, SyntaxNode) {
179	        let start = self.s.cursor() - 1;
180	
181	        // Determine number of opening backticks.
182	        let mut backticks = 1;
183	        while self.s.eat_if('`') {
184	            backticks += 1;
185	        }
186	
187	        // Special case for ``.
188	        if backticks == 2 {
189	            let nodes = vec![
190	                SyntaxNode::leaf(SyntaxKind::RawDelim, "`"),
191	                SyntaxNode::leaf(SyntaxKind::RawDelim, "`"),
192	            ];
193	            return (SyntaxKind::Raw, SyntaxNode::inner(SyntaxKind::Raw, nodes));
194	        }
195	
196	        // Find end of raw text.
197	        let mut found = 0;
198	        while found < backticks {
199	            match self.s.eat() {
200	                Some('`') => found += 1,
201	                Some(_) => found = 0,
202	                None => {
203	                    let message = "unclosed raw text";
204	                    let error = SyntaxNode::error(message, self.s.from(start));
205	                    return (SyntaxKind::Error, error);
206	                }
207	            }
208	        }
209	        let end = self.s.cursor();
210	
211	        let mut inner = Scanner::new(self.s.get(start + backticks..end - backticks));
212	        let inner_len = inner.string().len();
213	
214	        // Opening delimiter.
215	        let delim = SyntaxNode::leaf(SyntaxKind::RawDelim, self.s.from(end - backticks));
216	        let mut nodes = vec![delim.clone()];
217	
218	        let mut tag = None;
219	        let mut diff_future_tag_len = None;
220	        if delim.len() >= 3 {
221	            (tag, diff_future_tag_len) = Self::raw_lang_tag(&mut inner);
222	            if let Some(tag) = tag {
223	                nodes.push(SyntaxNode::leaf(SyntaxKind::RawLang, tag));
224	            }
225	            Self::blocky_raw(&mut inner, &mut nodes);
226	        } else {
227	            Self::inline_raw(&mut inner, &mut nodes);
228	        }
229	
230	        // Closing delimiter.
231	        nodes.push(delim);
232	
233	        let mut raw = SyntaxNode::inner(SyntaxKind::Raw, nodes);
234	
235	        Self::add_raw_warnings(&mut raw, backticks, diff_future_tag_len, tag, inner_len);
236	
237	        (SyntaxKind::Raw, raw)
238	    }
239	
240	    /// Lex the raw language tag into an optional string and return the length
241	    /// of the future language tag if it will differ in the next version.
242	    ///
243	    /// See [`Self::add_raw_warnings`] for more.
244	    fn raw_lang_tag<'a>(s: &mut Scanner<'a>) -> (Option<&'a str>, Option<usize>) {
245	        let start = s.cursor();
246	        let future_tag = s.eat_until(|c: char| c.is_whitespace() || c == '`');
247	        if future_tag.is_empty() {
248	            // Future tag is always longer than current tag, if empty, we have
249	            // no current tag either.
250	            return (None, None);
251	        }
252	        s.jump(start);
253	        let tag = s.eat_if(is_id_start).then(|| {
254	            s.eat_while(is_id_continue);
255	            s.from(start)
256	        });
257	        let diff_future_tag_len = tag
258	            .is_none_or(|tag| tag.len() != future_tag.len())
259	            .then_some(future_tag.len());
260	        (tag, diff_future_tag_len)
261	    }
262	
263	    /// Raw blocks parse a language tag, have smart behavior for trimming
264	    /// whitespace in the start/end lines, and trim common leading whitespace
265	    /// from all other lines as the "dedent". The exact behavior is described
266	    /// below.
267	    ///
268	    /// ### The initial line:
269	    /// - The language tag is already handled above.
270	    /// - We check the rest of the line and if all characters are whitespace,
271	    ///   trim it. Otherwise we trim a single leading space if present.
272	    ///   - If more trimmed characters follow on future lines, they will be
273	    ///     merged into the same trimmed element.
274	    /// - If we didn't trim the entire line, the rest is kept as text.
275	    ///
276	    /// ### Inner lines:
277	    /// - We determine the "dedent" by iterating over the lines. The dedent is
278	    ///   the minimum number of leading whitespace characters (not bytes) before
279	    ///   each line that has any non-whitespace characters.
280	    ///   - The opening delimiter's line does not contribute to the dedent, but
281	    ///     the closing delimiter's line does (even if that line is entirely
282	    ///     whitespace up to the delimiter).
283	    /// - We then trim the newline and dedent characters of each line, and add a
284	    ///   (potentially empty) text element of all remaining characters.
285	    ///
286	    /// ### The final line:
287	    /// - If the last line is entirely whitespace, it is trimmed.
288	    /// - Otherwise its text is kept like an inner line. However, if the last
289	    ///   non-whitespace character of the final line is a backtick, then one
290	    ///   ascii space (if present) is trimmed from the end.
291	    fn blocky_raw(s: &mut Scanner, nodes: &mut Vec<SyntaxNode>) {
292	        // The lines between the backticks.
293	        let mut lines = split_newlines(s.after());
294	
295	        // Determine dedent level.
296	        let dedent = lines
297	            .iter()
298	            .skip(1)
299	            .filter(|line| !line.chars().all(char::is_whitespace))
300	            // The line with the closing ``` is always taken into account
301	            .chain(lines.last())
302	            .map(|line| line.chars().take_while(|c| c.is_whitespace()).count())
303	            .min()
304	            .unwrap_or(0);
305	
306	        // Trim whitespace from the last line. Will be added as a `RawTrimmed`
307	        // kind by the check for `self.s.cursor() != inner_end` below.
308	        if lines.last().is_some_and(|last| last.chars().all(char::is_whitespace)) {
309	            lines.pop();
310	        } else if let Some(last) = lines.last_mut() {
311	            // If last line ends in a backtick, try to trim a single space. This
312	            // check must happen before we add the first line since the last and
313	            // first lines might be the same.
314	            if last.trim_end().ends_with('`') {
315	                *last = last.strip_suffix(' ').unwrap_or(last);
316	            }
317	        }
318	
319	        // A closure for pushing a leaf node and updating the cursor in one
320	        // step.
321	        let mut prev = s.cursor();
322	        let mut push_leaf = |kind, s: &Scanner| {
323	            nodes.push(SyntaxNode::leaf(kind, s.from(prev)));
324	            prev = s.cursor();
325	        };
326	
327	        let mut lines = lines.into_iter();
328	
329	        // Handle the first line: trim if all whitespace, or trim a single space
330	        // at the start. Note that the first line does not affect the dedent
331	        // value.
332	        if let Some(first_line) = lines.next() {
333	            if first_line.chars().all(char::is_whitespace) {
334	                s.advance(first_line.len());
335	                // This is the only spot we advance the scanner, but don't
336	                // immediately call `push_leaf`. But the rest of the function
337	                // ensures we will always add this text to a `RawTrimmed` later.
338	                debug_assert!(!s.done());
339	                // A proof by cases follows:
340	                // # First case: The loop runs
341	                // If the loop runs, there must be a newline following, so
342	                // `cursor != inner_end`. And if the loop runs, the first thing
343	                // it does is add a trimmed element.
344	                // # Second case: The final if-statement runs.
345	                // To _not_ reach the loop from here, we must have only one or
346	                // two lines:
347	                // 1. If one line, we cannot be here, because the first and last
348	                //    lines are the same, so this line will have been removed by
349	                //    the check for the last line being all whitespace.
350	                // 2. If two lines, the loop will run unless the last is fully
351	                //    whitespace, but if it is, it will have been popped, then
352	                //    the final if-statement will run because the text removed
353	                //    by the last line must include at least a newline, so
354	                //    `cursor != inner_end` here.
355	            } else {
356	                let line_end = s.cursor() + first_line.len();
357	                if s.eat_if(' ') {
358	                    // Trim a single space after the lang tag or backticks on
359	                    // the first line.
360	                    push_leaf(SyntaxKind::RawTrimmed, s);
361	                }
362	                // We know here that the rest of the line is non-empty.
363	                s.jump(line_end);
364	                push_leaf(SyntaxKind::Text, s);
365	            }
366	        }
367	
368	        // Add lines.
369	        for line in lines {
370	            let offset: usize = line.chars().take(dedent).map(char::len_utf8).sum();
371	            s.eat_newline();
372	            s.advance(offset);
373	            push_leaf(SyntaxKind::RawTrimmed, s);
374	            s.advance(line.len() - offset);
375	            push_leaf(SyntaxKind::Text, s);
376	        }
377	
378	        // Add final trimmed.
379	        if !s.done() {
380	            nodes.push(SyntaxNode::leaf(SyntaxKind::RawTrimmed, s.after()));
381	        }
382	    }
383	
384	    /// Inline raw text is split on lines with non-newlines as `Text` kinds and
385	    /// newlines as `RawTrimmed`. Inline raw text does not dedent the text, all
386	    /// non-newline whitespace is kept.
387	    fn inline_raw(s: &mut Scanner, nodes: &mut Vec<SyntaxNode>) {
388	        let mut prev = s.cursor();
389	        while !s.done() {
390	            if s.at(is_newline) {
391	                nodes.push(SyntaxNode::leaf(SyntaxKind::Text, s.from(prev)));
392	                prev = s.cursor();
393	                s.eat_newline();
394	                nodes.push(SyntaxNode::leaf(SyntaxKind::RawTrimmed, s.from(prev)));
395	                prev = s.cursor();
396	                continue;
397	            }
398	            s.eat();
399	        }
400	        nodes.push(SyntaxNode::leaf(SyntaxKind::Text, s.from(prev)));
401	    }
402	
403	    /// Add warnings if the raw language tag will differ in the next version of
404	    /// Typst or if there is a language tag but the raw text is empty.
405	    ///
406	    /// Currently, we parse the language tag only up to the end of a valid
407	    /// identifier or the first whitespace. So if we start with `C++`, the
408	    /// identifier `C` will be the language tag, and the raw text will start
409	    /// with `++`. If we start with `++C`, we will have no language tag and the
410	    /// raw text will start with `++C`.
411	    ///
412	    /// In the next version of Typst, we will parse all text up to the first
413	    /// whitespace or backtick, so tags like `C++` or `html.j2` or `$!#%@` can
414	    /// be written without issue
415	    ///
416	    /// However, this may cause some documents relying on the behavior of raw
417	    /// text starting like `C++` or `++C` to change, so we are giving a warning
418	    /// for those cases.
419	    fn add_raw_warnings(
420	        raw: &mut SyntaxNode,
421	        backticks: usize,
422	        diff_future_tag_len: Option<usize>,
423	        tag: Option<&str>,
424	        inner_len: usize,
425	    ) {
426	        // Add a warning if the tag will differ in the next version.
427	        if let Some(future_tag_len) = diff_future_tag_len {
428	            let future_range = backticks..backticks + future_tag_len;
429	            if let Some(tag) = tag {
430	                raw.warn_at(
431	                    future_range,
432	                    "no whitespace between language tag and raw text",
433	                );
434	                raw.hint(eco_format!(
435	                    "currently, Typst is treating `{tag}` as the language tag"
436	                ));
437	                raw.hint(
438	                    "in the next version of Typst, this will change and we will treat \
439	                        all text until the first whitespace as the language tag",
440	                );
441	                let tag_range = backticks..backticks + tag.len();
442	                raw.hint_at(tag_range.clone(), eco_format!(
443	                    "if the current behavior is correct, please add a space after `{tag}`"
444	                ));
445	                raw.hint_at(
446	                    tag_range,
447	                    "otherwise, add a space or newline after the initial backticks",
448	                );
449	            } else {
450	                raw.warn_at(future_range, "no whitespace before raw text");
451	                raw.hint(
452	                    "in the next version of Typst, this text will be treated as \
453	                        the language tag for this element",
454	                );
455	                raw.hint("to avoid this, add a space after the initial backticks");
456	            }
457	        } else if let Some(tag) = tag
458	            && inner_len == tag.len()
459	        {
460	            // Empty with no tag/ws is only possible with exactly two backticks,
461	            // which is handled by the caller.
462	            raw.warn("empty raw text");
463	            raw.hint(eco_format!("Typst is treating `{tag}` as the language tag"));
464	            let tag_range = backticks..backticks + tag.len();
465	            raw.hint_at(
466	                tag_range,
467	                "to treat this as text, add a space after the initial backticks",
468	            );
469	        }
470	    }
471	}
