473	/// Markup.
474	impl Lexer<'_> {
475	    fn markup(&mut self, start: usize, c: char) -> SyntaxKind {
476	        match c {
477	            '\\' => self.backslash(),
478	            'h' if self.s.eat_if("ttp://") => self.link(),
479	            'h' if self.s.eat_if("ttps://") => self.link(),
480	            '<' if self.s.at(is_id_continue) => self.label(),
481	            '@' if self.s.at(is_id_continue) => self.ref_marker(),
482	
483	            '.' if self.s.eat_if("..") => SyntaxKind::Shorthand,
484	            '-' if self.s.eat_if("--") => SyntaxKind::Shorthand,
485	            '-' if self.s.eat_if('-') => SyntaxKind::Shorthand,
486	            '-' if self.s.eat_if('?') => SyntaxKind::Shorthand,
487	            '-' if self.s.at(char::is_numeric) => SyntaxKind::Shorthand,
488	            '*' if !self.in_word() => SyntaxKind::Star,
489	            '_' if !self.in_word() => SyntaxKind::Underscore,
490	
491	            '#' => SyntaxKind::Hash,
492	            '[' => SyntaxKind::LeftBracket,
493	            ']' => SyntaxKind::RightBracket,
494	            '\'' => SyntaxKind::SmartQuote,
495	            '"' => SyntaxKind::SmartQuote,
496	            '$' => SyntaxKind::Dollar,
497	            '~' => SyntaxKind::Shorthand,
498	            ':' => SyntaxKind::Colon,
499	            '=' => {
500	                self.s.eat_while('=');
501	                if self.space_or_end() { SyntaxKind::HeadingMarker } else { self.text() }
502	            }
503	            '-' if self.space_or_end() => SyntaxKind::ListMarker,
504	            '+' if self.space_or_end() => SyntaxKind::EnumMarker,
505	            '/' if self.space_or_end() => SyntaxKind::TermMarker,
506	            '0'..='9' => self.numbering(start),
507	
508	            _ => self.text(),
509	        }
510	    }
511	
512	    fn backslash(&mut self) -> SyntaxKind {
513	        if self.s.eat_if("u{") {
514	            let hex = self.s.eat_while(char::is_ascii_alphanumeric);
515	            if !self.s.eat_if('}') {
516	                return self.error("unclosed Unicode escape sequence");
517	            }
518	
519	            if u32::from_str_radix(hex, 16)
520	                .ok()
521	                .and_then(std::char::from_u32)
522	                .is_none()
523	            {
524	                return self.error(eco_format!("invalid Unicode codepoint: {hex}"));
525	            }
526	
527	            return SyntaxKind::Escape;
528	        }
529	
530	        if self.s.done() || self.s.at(char::is_whitespace) {
531	            SyntaxKind::Linebreak
532	        } else {
533	            self.s.eat();
534	            SyntaxKind::Escape
535	        }
536	    }
537	
538	    fn link(&mut self) -> SyntaxKind {
539	        let (link, balanced) = link_prefix(self.s.after());
540	        self.s.advance(link.len());
541	
542	        if !balanced {
543	            return self.error(
544	                "automatic links cannot contain unbalanced brackets, \
545	                 use the `link` function instead",
546	            );
547	        }
548	
549	        SyntaxKind::Link
550	    }
551	
552	    fn numbering(&mut self, start: usize) -> SyntaxKind {
553	        self.s.eat_while(char::is_ascii_digit);
554	
555	        let read = self.s.from(start);
556	        if self.s.eat_if('.') && self.space_or_end() && read.parse::<u64>().is_ok() {
557	            return SyntaxKind::EnumMarker;
558	        }
559	
560	        self.text()
561	    }
562	
563	    fn ref_marker(&mut self) -> SyntaxKind {
564	        self.s.eat_while(is_valid_in_label_literal);
565	
566	        // Don't include the trailing characters likely to be part of text.
567	        while matches!(self.s.scout(-1), Some('.' | ':')) {
568	            self.s.uneat();
569	        }
570	
571	        SyntaxKind::RefMarker
572	    }
573	
574	    fn label(&mut self) -> SyntaxKind {
575	        let label = self.s.eat_while(is_valid_in_label_literal);
576	        if label.is_empty() {
577	            return self.error("label cannot be empty");
578	        }
579	
580	        if !self.s.eat_if('>') {
581	            return self.error("unclosed label");
582	        }
583	
584	        SyntaxKind::Label
585	    }
586	
587	    fn text(&mut self) -> SyntaxKind {
588	        macro_rules! table {
589	            ($(|$c:literal)*) => {
590	                static TABLE: [bool; 128] = {
591	                    let mut t = [false; 128];
592	                    $(t[$c as usize] = true;)*
593	                    t
594	                };
595	            };
596	        }
597	
598	        table! {
599	            | ' ' | '\t' | '\n' | '\x0b' | '\x0c' | '\r' | '\\' | '/'
600	            | '[' | ']' | '~' | '-' | '.' | '\'' | '"' | '*' | '_'
601	            | ':' | 'h' | '`' | '$' | '<' | '>' | '@' | '#'
602	        };
603	
604	        loop {
605	            self.s.eat_until(|c: char| {
606	                TABLE.get(c as usize).copied().unwrap_or_else(|| c.is_whitespace())
607	            });
608	
609	            // Continue with the same text node if the thing would become text
610	            // anyway.
611	            let mut s = self.s;
612	            match s.eat() {
613	                Some(' ') if s.at(char::is_alphanumeric) => {}
614	                Some('/') if !s.at(['/', '*']) => {}
615	                Some('-') if !s.at(['-', '?']) => {}
616	                Some('.') if !s.at("..") => {}
617	                Some('h') if !s.at("ttp://") && !s.at("ttps://") => {}
618	                Some('@') if !s.at(is_valid_in_label_literal) => {}
619	                _ => break,
620	            }
621	
622	            self.s = s;
623	        }
624	
625	        SyntaxKind::Text
626	    }
627	
628	    fn in_word(&self) -> bool {
629	        let wordy = |c: Option<char>| {
630	            c.is_some_and(|c| {
631	                c.is_alphanumeric()
632	                    && !matches!(
633	                        c.script(),
634	                        Script::Han
635	                            | Script::Hiragana
636	                            | Script::Katakana
637	                            | Script::Hangul
638	                    )
639	            })
640	        };
641	        let prev = self.s.scout(-2);
642	        let next = self.s.peek();
643	        wordy(prev) && wordy(next)
644	    }
645	
646	    fn space_or_end(&self) -> bool {
647	        self.s.done()
648	            || self.s.at(char::is_whitespace)
649	            || self.s.at("//")
650	            || self.s.at("/*")
651	    }
652	}
