654	/// Math.
655	impl Lexer<'_> {
656	    fn math(&mut self, start: usize, c: char) -> (SyntaxKind, Option<SyntaxNode>) {
657	        let kind = match c {
658	            '\\' => self.backslash(),
659	            '"' => self.string(),
660	
661	            '-' if self.s.eat_if(">>") => SyntaxKind::MathShorthand,
662	            '-' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
663	            '-' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
664	            ':' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
665	            ':' if self.s.eat_if(":=") => SyntaxKind::MathShorthand,
666	            '!' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
667	            '.' if self.s.eat_if("..") => SyntaxKind::MathShorthand,
668	            '<' if self.s.eat_if("==>") => SyntaxKind::MathShorthand,
669	            '<' if self.s.eat_if("-->") => SyntaxKind::MathShorthand,
670	            '<' if self.s.eat_if("--") => SyntaxKind::MathShorthand,
671	            '<' if self.s.eat_if("-<") => SyntaxKind::MathShorthand,
672	            '<' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
673	            '<' if self.s.eat_if("<-") => SyntaxKind::MathShorthand,
674	            '<' if self.s.eat_if("<<") => SyntaxKind::MathShorthand,
675	            '<' if self.s.eat_if("=>") => SyntaxKind::MathShorthand,
676	            '<' if self.s.eat_if("==") => SyntaxKind::MathShorthand,
677	            '<' if self.s.eat_if("~~") => SyntaxKind::MathShorthand,
678	            '<' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
679	            '<' if self.s.eat_if('<') => SyntaxKind::MathShorthand,
680	            '<' if self.s.eat_if('-') => SyntaxKind::MathShorthand,
681	            '<' if self.s.eat_if('~') => SyntaxKind::MathShorthand,
682	            '>' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
683	            '>' if self.s.eat_if(">>") => SyntaxKind::MathShorthand,
684	            '=' if self.s.eat_if("=>") => SyntaxKind::MathShorthand,
685	            '=' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
686	            '=' if self.s.eat_if(':') => SyntaxKind::MathShorthand,
687	            '>' if self.s.eat_if('=') => SyntaxKind::MathShorthand,
688	            '>' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
689	            '|' if self.s.eat_if("->") => SyntaxKind::MathShorthand,
690	            '|' if self.s.eat_if("=>") => SyntaxKind::MathShorthand,
691	            '|' if self.s.eat_if('|') => SyntaxKind::MathShorthand,
692	            '~' if self.s.eat_if("~>") => SyntaxKind::MathShorthand,
693	            '~' if self.s.eat_if('>') => SyntaxKind::MathShorthand,
694	            '*' | '-' | '~' => SyntaxKind::MathShorthand,
695	
696	            ',' => SyntaxKind::Comma,
697	            ';' => SyntaxKind::Semicolon,
698	
699	            '#' => SyntaxKind::Hash,
700	            '_' => SyntaxKind::Underscore,
701	            '$' => SyntaxKind::Dollar,
702	            '/' => SyntaxKind::Slash,
703	            '^' => SyntaxKind::Hat,
704	            '&' => SyntaxKind::MathAlignPoint,
705	            '√' | '∛' | '∜' => SyntaxKind::Root,
706	            '!' => SyntaxKind::Bang,
707	
708	            '\'' => {
709	                self.s.eat_while('\'');
710	                SyntaxKind::MathPrimes
711	            }
712	
713	            // Delimiters have two special cases:
714	            // 1. We lex parentheses as `{Left,Right}Paren` and convert back to
715	            //    `MathOpening`/`MathClosing` in the parser if not used for an
716	            //    actual function call.
717	            // 2. The `[|` and `|]` shorthands become `MathShorthand` nested
718	            //    inside `MathOpening` or `MathClosing`.
719	            '(' => SyntaxKind::LeftParen,
720	            ')' => SyntaxKind::RightParen,
721	            '[' if self.s.eat_if('|') => {
722	                let kind = SyntaxKind::MathOpening;
723	                let leaf =
724	                    SyntaxNode::leaf(SyntaxKind::MathShorthand, self.s.from(start));
725	                let node = SyntaxNode::inner(kind, vec![leaf]);
726	                return (kind, Some(node));
727	            }
728	            '|' if self.s.eat_if(']') => {
729	                let kind = SyntaxKind::MathClosing;
730	                let leaf =
731	                    SyntaxNode::leaf(SyntaxKind::MathShorthand, self.s.from(start));
732	                let node = SyntaxNode::inner(kind, vec![leaf]);
733	                return (kind, Some(node));
734	            }
735	            c if default_math_class(c) == Some(MathClass::Opening) => {
736	                SyntaxKind::MathOpening
737	            }
738	            c if default_math_class(c) == Some(MathClass::Closing) => {
739	                SyntaxKind::MathClosing
740	            }
741	
742	            // Numbers.
743	            c if c.is_numeric() => {
744	                self.s.eat_while(char::is_numeric);
745	                let mut s = self.s;
746	                if s.eat_if('.') && !s.eat_while(char::is_numeric).is_empty() {
747	                    self.s = s;
748	                }
749	                SyntaxKind::MathNumber
750	            }
751	
752	            // An identifier, a single letter, or a symbol.
753	            c => {
754	                let char_len = c.len_utf8();
755	                // First get the length of an entire identifier and of the
756	                // initial grapheme. Also move `self.s` forward to match the
757	                // identifier.
758	                let identifier_len = if is_math_id_start(c) {
759	                    char_len + self.s.eat_while(is_math_id_continue).len()
760	                } else {
761	                    0
762	                };
763	                let after_start = self.s.get(start..self.s.string().len());
764	                let single_grapheme_len =
765	                    after_start.graphemes(true).next().map_or(char_len, str::len);
766	
767	                // Determine the syntax kind by comparing lengths:
768	                if identifier_len > single_grapheme_len {
769	                    // More than one grapheme, we lex this as an identifier,
770	                    // potentially with a field access. We do not try to handle
771	                    // any non-identifier characters following that would attach
772	                    // as a grapheme cluster to the final character.
773	                    let (kind, node) = self.math_ident_or_field(start);
774	                    return (kind, Some(node));
775	                } else if identifier_len == single_grapheme_len {
776	                    // We treat valid identifiers with just one grapheme as
777	                    // single letters.
778	                    SyntaxKind::MathLetter
779	                } else {
780	                    // Non-identifier graphemes are treated as symbols. Note: It
781	                    // is possible for `identifier_len != 0` here due to
782	                    // characters like U+20DD COMBINING ENCLOSING CIRCLE that
783	                    // have the Unicode `Grapheme_Cluster_Break=Extend|Prepend`
784	                    // properties but not the `xid_continue` property.
785	                    self.s.jump(start + single_grapheme_len);
786	                    SyntaxKind::MathSymbol
787	                }
788	            }
789	        };
790	        (kind, None)
791	    }
792	
793	    /// Parse a single `MathIdent` or an entire `MathFieldAccess`.
794	    fn math_ident_or_field(&mut self, start: usize) -> (SyntaxKind, SyntaxNode) {
795	        let mut kind = SyntaxKind::MathIdent;
796	        let mut node = SyntaxNode::leaf(kind, self.s.from(start));
797	        while let Some(ident) = self.maybe_dot_ident() {
798	            kind = SyntaxKind::MathFieldAccess;
799	            let field_children = vec![
800	                node,
801	                SyntaxNode::leaf(SyntaxKind::Dot, '.'),
802	                SyntaxNode::leaf(SyntaxKind::MathIdent, ident),
803	            ];
804	            node = SyntaxNode::inner(kind, field_children);
805	        }
806	        (kind, node)
807	    }
808	
809	    /// If at a dot and a math identifier, eat and return the identifier.
810	    fn maybe_dot_ident(&mut self) -> Option<&str> {
811	        if self.s.scout(1).is_some_and(is_math_id_start) && self.s.eat_if('.') {
812	            let ident_start = self.s.cursor();
813	            self.s.eat();
814	            self.s.eat_while(is_math_id_continue);
815	            Some(self.s.from(ident_start))
816	        } else {
817	            None
818	        }
819	    }
820	
821	    /// Handle named arguments in math function call.
822	    pub fn maybe_math_named_arg(&mut self, start: usize) -> Option<SyntaxNode> {
823	        let cursor = self.s.cursor();
824	        self.s.jump(start);
825	        if self.s.eat_if(is_id_start) {
826	            self.s.eat_while(is_id_continue);
827	            // Check that a colon directly follows the identifier, and not the
828	            // `:=` or `::=` math shorthands.
829	            if self.s.at(':') && !self.s.at(":=") && !self.s.at("::=") {
830	                // Check that the identifier is not just `_`.
831	                let node = if self.s.from(start) != "_" {
832	                    SyntaxNode::leaf(SyntaxKind::Ident, self.s.from(start))
833	                } else {
834	                    let message = "expected identifier, found underscore";
835	                    SyntaxNode::error(message, self.s.from(start))
836	                };
837	                return Some(node);
838	            }
839	        }
840	        self.s.jump(cursor);
841	        None
842	    }
843	
844	    /// Handle spread arguments in math function call.
845	    pub fn maybe_math_spread_arg(&mut self, start: usize) -> Option<SyntaxNode> {
846	        let cursor = self.s.cursor();
847	        self.s.jump(start);
848	        if self.s.eat_if("..") {
849	            // We only infer a spread operator if it is not followed by:
850	            // - a space/trivia/end
851	            // - a dot (this would clash with the `...` math shorthand)
852	            // - an end of arg character: `,`, `;`, ')', `$` (spreads nothing)
853	            if !self.space_or_end() && !self.s.at(['.', ',', ';', ')', '$']) {
854	                let node = SyntaxNode::leaf(SyntaxKind::Dots, self.s.from(start));
855	                return Some(node);
856	            }
857	        }
858	        self.s.jump(cursor);
859	        None
860	    }
861	}
