863	/// Code.
864	impl Lexer<'_> {
865	    fn code(&mut self, start: usize, c: char) -> SyntaxKind {
866	        match c {
867	            '<' if self.s.at(is_id_continue) => self.label(),
868	            '0'..='9' => self.number(start, c),
869	            '.' if self.s.at(char::is_ascii_digit) => self.number(start, c),
870	            '"' => self.string(),
871	
872	            '=' if self.s.eat_if('=') => SyntaxKind::EqEq,
873	            '!' if self.s.eat_if('=') => SyntaxKind::ExclEq,
874	            '<' if self.s.eat_if('=') => SyntaxKind::LtEq,
875	            '>' if self.s.eat_if('=') => SyntaxKind::GtEq,
876	            '+' if self.s.eat_if('=') => SyntaxKind::PlusEq,
877	            '-' | '\u{2212}' if self.s.eat_if('=') => SyntaxKind::HyphEq,
878	            '*' if self.s.eat_if('=') => SyntaxKind::StarEq,
879	            '/' if self.s.eat_if('=') => SyntaxKind::SlashEq,
880	            '.' if self.s.eat_if('.') => SyntaxKind::Dots,
881	            '=' if self.s.eat_if('>') => SyntaxKind::Arrow,
882	
883	            '{' => SyntaxKind::LeftBrace,
884	            '}' => SyntaxKind::RightBrace,
885	            '[' => SyntaxKind::LeftBracket,
886	            ']' => SyntaxKind::RightBracket,
887	            '(' => SyntaxKind::LeftParen,
888	            ')' => SyntaxKind::RightParen,
889	            '$' => SyntaxKind::Dollar,
890	            ',' => SyntaxKind::Comma,
891	            ';' => SyntaxKind::Semicolon,
892	            ':' => SyntaxKind::Colon,
893	            '.' => SyntaxKind::Dot,
894	            '+' => SyntaxKind::Plus,
895	            '-' | '\u{2212}' => SyntaxKind::Minus,
896	            '*' => SyntaxKind::Star,
897	            '/' => SyntaxKind::Slash,
898	            '=' => SyntaxKind::Eq,
899	            '<' => SyntaxKind::Lt,
900	            '>' => SyntaxKind::Gt,
901	
902	            c if is_id_start(c) => self.ident(start),
903	
904	            c => self.invalid_char_in_code(c),
905	        }
906	    }
