908	    /// Error for an invalid character in code, but try to give good hints for
909	    /// commonly confusing operators.
910	    fn invalid_char_in_code(&mut self, c: char) -> SyntaxKind {
911	        let invalid_char = || eco_format!("the character `{c}` is not valid in code");
912	        let invalid_str = |s: &str| eco_format!("`{s}` is not valid in code");
913	        match c {
914	            // Give a custom hint if we immediately follow a hash.
915	            _ if self.s.scout(-2) == Some('#') => {
916	                self.error(invalid_char());
917	                // This is only an accurate hint if we just came from markup or
918	                // math, but `#!` or `##` in code should be rare enough that
919	                // it's fine (and the first hash will produce its own error).
920	                self.hint("the preceding hash is causing this to parse in code mode");
921	                self.hint("try escaping the preceding hash: `\\#`");
922	                // The span for these hints isn't great, but it's hard to fix.
923	            }
924	            '#' => {
925	                self.error(invalid_char());
926	                self.hint("you are already in code mode");
927	                self.hint("try removing the `#`");
928	            }
929	            '&' if self.s.eat_if('&') => {
930	                self.error(invalid_str("&&"));
931	                self.hint("in Typst, `and` is used for logical AND");
932	            }
933	            '|' if self.s.eat_if('|') => {
934	                self.error(invalid_str("||"));
935	                self.hint("in Typst, `or` is used for logical OR");
936	            }
937	            '!' => {
938	                self.error(invalid_char());
939	                self.hint("in Typst, `not` is used for negation");
940	                self.hint("or did you mean to write `!=` for not-equal?");
941	            }
942	            '~' if self.s.eat_if('=') => {
943	                self.error(invalid_str("~="));
944	                self.hint("in Typst, `!=` is used for not-equal");
945	            }
946	            _ => {
947	                self.error(invalid_char());
948	            }
949	        }
950	        SyntaxKind::Error
951	    }
