953	    fn ident(&mut self, start: usize) -> SyntaxKind {
954	        self.s.eat_while(is_id_continue);
955	        let ident = self.s.from(start);
956	
957	        let prev = self.s.get(0..start);
958	        if (!prev.ends_with(['.', '@']) || prev.ends_with(".."))
959	            && let Some(keyword) = keyword(ident)
960	        {
961	            return keyword;
962	        }
963	
964	        if ident == "_" { SyntaxKind::Underscore } else { SyntaxKind::Ident }
965	    }
966	
967	    /// Lex a single number, either an integer or a float, possibly with a
968	    /// numeric suffix (`pt`, `deg`, `%`, etc.). Integers may also have a prefix
969	    /// for binary, octal, or hexadecimal bases, but only base-10 integers can
970	    /// have a numeric suffix (if so, they will be treated as floats in the
971	    /// AST).
972	    ///
973	    /// Floating point numbers can use exponent notation with `e` or `E`, such
974	    /// as `5.0e-3in` for `0.005in`.
975	    fn number(&mut self, start: usize, first_c: char) -> SyntaxKind {
976	        // Handle alternative integer bases.
977	        let base = match first_c {
978	            '0' if self.s.eat_if('x') => Some(NonDecimalBase::Hex),
979	            '0' if self.s.eat_if('o') => Some(NonDecimalBase::Octal),
980	            '0' if self.s.eat_if('b') => Some(NonDecimalBase::Binary),
981	            _ => None,
982	        };
983	
984	        // Read the initial digits.
985	        if base == Some(NonDecimalBase::Hex) {
986	            self.s.eat_while(char::is_ascii_alphanumeric);
987	        } else {
988	            self.s.eat_while(char::is_ascii_digit);
989	        }
990	
991	        // Read floating point digits and exponents.
992	        let mut is_float = false;
993	        if base.is_none() {
994	            // Read digits following a dot. Make sure not to confuse a spread
995	            // operator or a method call for the decimal separator.
996	            if first_c == '.' {
997	                is_float = true; // We already ate the trailing digits above.
998	            } else if !self.s.at("..")
999	                && !self.s.scout(1).is_some_and(is_id_start)
1000	                && self.s.eat_if('.')
1001	            {
1002	                is_float = true;
1003	                self.s.eat_while(char::is_ascii_digit);
1004	            }
1005	
1006	            // Read the exponent.
1007	            if !self.s.at("em") && self.s.eat_if(['e', 'E']) {
1008	                is_float = true;
1009	                self.s.eat_if(['+', '-']);
1010	                self.s.eat_while(char::is_ascii_digit);
1011	            }
1012	        }
1013	
1014	        let number = self.s.from(start);
1015	        let suffix = self.s.eat_while(|c: char| c.is_ascii_alphanumeric() || c == '%');
1016	
1017	        let mut suffix_result = match suffix {
1018	            "" => Ok(None),
1019	            "pt" | "mm" | "cm" | "in" | "deg" | "rad" | "em" | "fr" | "%" => Ok(Some(())),
1020	            _ => Err(eco_format!("invalid number suffix: `{suffix}`")),
1021	        };
1022	
1023	        let number_result = if is_float {
1024	            if number.parse::<f64>().is_err() {
1025	                // The only invalid case should be when a float lacks digits after
1026	                // the exponent: e.g. `1.2e`, `2.3E-`, or `1EM`.
1027	                Err(eco_format!("invalid floating point number: `{number}`"))
1028	            } else {
1029	                Ok(())
1030	            }
1031	        } else if let Some(non_decimal) = base {
1032	            let name = non_decimal.name();
1033	            // The index `[2..]` skips the leading `0b`/`0o`/`0x`.
1034	            match i64::from_str_radix(&number[2..], non_decimal as u32) {
1035	                Ok(_) if suffix.is_empty() => Ok(()),
1036	                Ok(value) => {
1037	                    if suffix_result.is_ok() {
1038	                        suffix_result = Err(eco_format!(
1039	                            "try using a decimal number: `{value}{suffix}`"
1040	                        ));
1041	                    }
1042	                    Err(eco_format!("{name} numbers cannot have a suffix"))
1043	                }
1044	                Err(e) if *e.kind() == IntErrorKind::Empty => Err(eco_format!(
1045	                    "expected a{} {name} number",
1046	                    if non_decimal == NonDecimalBase::Octal { "n" } else { "" },
1047	                )),
1048	                Err(_) if suffix_result.is_err() => {
1049	                    // We're already erroring, tell them about the invalid
1050	                    // integer first.
1051	                    Err(eco_format!("invalid {name} number: `{number}`"))
1052	                }
1053	                // Invalid digits and positive overflow errors are handled in
1054	                // the AST.
1055	                Err(_) => Ok(()),
1056	            }
1057	        } else {
1058	            // Decimal integer errors are handled in the AST. Note that
1059	            // too-large decimal integers that have suffixes will be silently
1060	            // treated as floats.
1061	            Ok(())
1062	        };
1063	
1064	        // Return our number or write an error with helpful hints.
1065	        match (number_result, suffix_result) {
1066	            // Valid numbers :D
1067	            (Ok(()), Ok(None)) if is_float => SyntaxKind::Float,
1068	            (Ok(()), Ok(None)) => SyntaxKind::Int,
1069	            (Ok(()), Ok(Some(()))) => SyntaxKind::Numeric,
1070	            // Invalid numbers :(
1071	            (Err(number_err), Err(suffix_err)) => {
1072	                let error = self.error(number_err);
1073	                self.hint(suffix_err);
1074	                error
1075	            }
1076	            (Ok(()), Err(msg)) | (Err(msg), Ok(_)) => self.error(msg),
1077	        }
1078	    }
1079	
1080	    fn string(&mut self) -> SyntaxKind {
1081	        let mut escaped = false;
1082	        self.s.eat_until(|c| {
1083	            let stop = c == '"' && !escaped;
1084	            escaped = c == '\\' && !escaped;
1085	            stop
1086	        });
1087	
1088	        if !self.s.eat_if('"') {
1089	            return self.error("unclosed string");
1090	        }
1091	
1092	        SyntaxKind::Str
1093	    }
1094	}
1095	
1096	/// Try to parse an identifier into a keyword.
1097	fn keyword(ident: &str) -> Option<SyntaxKind> {
1098	    Some(match ident {
1099	        "none" => SyntaxKind::None,
1100	        "auto" => SyntaxKind::Auto,
1101	        "true" => SyntaxKind::Bool,
1102	        "false" => SyntaxKind::Bool,
1103	        "not" => SyntaxKind::Not,
1104	        "and" => SyntaxKind::And,
1105	        "or" => SyntaxKind::Or,
1106	        "let" => SyntaxKind::Let,
1107	        "set" => SyntaxKind::Set,
1108	        "show" => SyntaxKind::Show,
1109	        "context" => SyntaxKind::Context,
1110	        "if" => SyntaxKind::If,
1111	        "else" => SyntaxKind::Else,
1112	        "for" => SyntaxKind::For,
1113	        "in" => SyntaxKind::In,
1114	        "while" => SyntaxKind::While,
1115	        "break" => SyntaxKind::Break,
1116	        "continue" => SyntaxKind::Continue,
1117	        "return" => SyntaxKind::Return,
1118	        "import" => SyntaxKind::Import,
1119	        "include" => SyntaxKind::Include,
1120	        "as" => SyntaxKind::As,
1121	        _ => return None,
1122	    })
1123	}
1124	
1125	trait ScannerExt {
1126	    fn advance(&mut self, by: usize);
1127	    fn eat_newline(&mut self) -> bool;
1128	}
1129	
1130	impl ScannerExt for Scanner<'_> {
1131	    fn advance(&mut self, by: usize) {
1132	        self.jump(self.cursor() + by);
1133	    }
1134	
1135	    fn eat_newline(&mut self) -> bool {
1136	        let ate = self.eat_if(is_newline);
1137	        if ate && self.before().ends_with('\r') {
1138	            self.eat_if('\n');
1139	        }
1140	        ate
1141	    }
1142	}
1143	
1144	/// Whether a character will become a space token, either
1145	/// [`SyntaxKind::SpaceNoNewline`] or [`SyntaxKind::SpaceWithNewline`].
1146	#[inline]
1147	fn is_space(character: char, mode: SyntaxMode) -> bool {
1148	    match mode {
1149	        SyntaxMode::Markup => matches!(character, ' ' | '\t') || is_newline(character),
1150	        _ => character.is_whitespace(),
1151	    }
1152	}
1153	
1154	/// Whether a character is interpreted as a newline by Typst.
1155	#[inline]
1156	pub fn is_newline(character: char) -> bool {
1157	    matches!(
1158	        character,
1159	        // Line Feed, Vertical Tab, Form Feed, Carriage Return.
1160	        '\n' | '\x0B' | '\x0C' | '\r' |
1161	        // Next Line, Line Separator, Paragraph Separator.
1162	        '\u{0085}' | '\u{2028}' | '\u{2029}'
1163	    )
1164	}
1165	
1166	/// Extracts a prefix of the text that is a link and also returns whether the
1167	/// parentheses and brackets in the link were balanced.
1168	pub fn link_prefix(text: &str) -> (&str, bool) {
1169	    let mut s = unscanny::Scanner::new(text);
1170	    let mut brackets = Vec::new();
1171	
1172	    #[rustfmt::skip]
1173	    s.eat_while(|c: char| {
1174	        match c {
1175	            | '0' ..= '9'
1176	            | 'a' ..= 'z'
1177	            | 'A' ..= 'Z'
1178	            | '!' | '#' | '$' | '%' | '&' | '*' | '+'
1179	            | ',' | '-' | '.' | '/' | ':' | ';' | '='
1180	            | '?' | '@' | '_' | '~' | '\'' => true,
1181	            '[' => {
1182	                brackets.push(b'[');
1183	                true
1184	            }
1185	            '(' => {
1186	                brackets.push(b'(');
1187	                true
1188	            }
1189	            ']' => brackets.pop() == Some(b'['),
1190	            ')' => brackets.pop() == Some(b'('),
1191	            _ => false,
1192	        }
1193	    });
1194	
1195	    // Don't include the trailing characters likely to be part of text.
1196	    while matches!(s.scout(-1), Some('!' | ',' | '.' | ':' | ';' | '?' | '\'')) {
1197	        s.uneat();
1198	    }
1199	
1200	    (s.before(), brackets.is_empty())
1201	}
1202	
1203	/// Split text at newlines. These newline characters are not kept.
1204	pub fn split_newlines(text: &str) -> Vec<&str> {
1205	    let mut s = Scanner::new(text);
1206	    let mut lines = Vec::new();
1207	    let mut start = 0;
1208	    let mut end = 0;
1209	
1210	    while let Some(c) = s.eat() {
1211	        if is_newline(c) {
1212	            if c == '\r' {
1213	                s.eat_if('\n');
1214	            }
1215	
1216	            lines.push(&text[start..end]);
1217	            start = s.cursor();
1218	        }
1219	        end = s.cursor();
1220	    }
1221	
1222	    lines.push(&text[start..]);
1223	    lines
1224	}
1225	
1226	/// Count the number of newlines in text.
1227	fn count_newlines(text: &str) -> usize {
1228	    let mut newlines = 0;
1229	    let mut s = Scanner::new(text);
1230	    while let Some(c) = s.eat() {
1231	        if is_newline(c) {
1232	            if c == '\r' {
1233	                s.eat_if('\n');
1234	            }
1235	            newlines += 1;
1236	        }
1237	    }
1238	    newlines
1239	}
1240	
1241	/// Whether a string is a valid Typst identifier.
1242	///
1243	/// In addition to what is specified in the [Unicode Standard][uax31], we allow:
1244	/// - `_` as a starting character,
1245	/// - `_` and `-` as continuing characters.
1246	///
1247	/// [uax31]: http://www.unicode.org/reports/tr31/
1248	#[inline]
1249	pub fn is_ident(string: &str) -> bool {
1250	    let mut chars = string.chars();
1251	    chars
1252	        .next()
1253	        .is_some_and(|c| is_id_start(c) && chars.all(is_id_continue))
1254	}
1255	
1256	/// Whether a character can start an identifier.
1257	#[inline]
1258	pub fn is_id_start(c: char) -> bool {
1259	    is_xid_start(c) || c == '_'
1260	}
1261	
1262	/// Whether a character can continue an identifier.
1263	#[inline]
1264	pub fn is_id_continue(c: char) -> bool {
1265	    is_xid_continue(c) || c == '_' || c == '-'
1266	}
1267	
1268	/// Whether a character can start an identifier in math.
1269	#[inline]
1270	fn is_math_id_start(c: char) -> bool {
1271	    is_xid_start(c)
1272	}
1273	
1274	/// Whether a character can continue an identifier in math.
1275	#[inline]
1276	fn is_math_id_continue(c: char) -> bool {
1277	    is_xid_continue(c) && c != '_'
1278	}
1279	
1280	/// Whether a character can be part of a label literal's name.
1281	#[inline]
1282	fn is_valid_in_label_literal(c: char) -> bool {
1283	    is_id_continue(c) || matches!(c, ':' | '.')
1284	}
1285	
1286	/// Returns true if this string is valid in a label literal.
1287	pub fn is_valid_label_literal_id(id: &str) -> bool {
1288	    !id.is_empty() && id.chars().all(is_valid_in_label_literal)
1289	}
